import * as THREE from '../vendor/three.module.js';
const clamp=THREE.MathUtils.clamp;
function createRenderer(container,{alpha=false}={}){const r=new THREE.WebGLRenderer({antialias:true,alpha});r.setPixelRatio(Math.min(devicePixelRatio,1.6));r.outputColorSpace=THREE.SRGBColorSpace;r.toneMapping=THREE.ACESFilmicToneMapping;r.toneMappingExposure=1.15;container.querySelector('.loading')?.remove();container.append(r.domElement);return r}
function dimensions(container,renderer,camera,draw){const resize=()=>{let w=container.clientWidth,h=container.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();draw()};new ResizeObserver(resize).observe(container);resize();return resize}
const material=(color,more={})=>new THREE.MeshStandardMaterial({color,roughness:.87,...more});
function block(group,w,h,d,color,x,y,z){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh}
function hipRoof(group,x,z,w,d,height=2){const y=3.35;const v=new Float32Array([x-w/2,y,z-d/2,x+w/2,y,z-d/2,x+w/2,y,z+d/2,x-w/2,y,z+d/2,x,y+height,z-d*.22,x,y+height,z+d*.22]);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(v,3));g.setIndex([0,4,1,1,4,5,1,5,2,2,5,3,3,5,4,3,4,0]);g.computeVertexNormals();const m=new THREE.Mesh(g,material(0x4b504b,{side:THREE.DoubleSide}));m.castShadow=true;group.add(m);const e=new THREE.LineSegments(new THREE.EdgesGeometry(g),new THREE.LineBasicMaterial({color:0x262e29}));group.add(e)}
function tree(g,x,z,size=1){block(g,.3*size,3.5*size,.3*size,0x6e6244,x,1.75*size,z);for(let j=0;j<4;j++){const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry((1.2+j*.15)*size,2),material([0x68794c,0x76864e,0x516a43,0x8a945c][j]));mesh.position.set(x+Math.sin(j*2)*.55*size,(3.1+j*.36)*size,z+Math.cos(j*2)*.55*size);mesh.scale.y=.85;mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh)}}
function lawnTexture(){const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#91a171';ctx.fillRect(0,0,256,256);let seed=937;for(let i=0;i<14000;i++){seed=(seed*16807)%2147483647;const x=seed%256;seed=(seed*16807)%2147483647;const y=seed%256;ctx.fillStyle=i%2?'#9daa7b':'#879563';ctx.fillRect(x,y,1,2)}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(10,14);t.colorSpace=THREE.SRGBColorSpace;return t}
export function createLot(container){const scene=new THREE.Scene();scene.background=new THREE.Color(0xd5ddc9);scene.fog=new THREE.Fog(0xd5ddc9,90,165);scene.add(new THREE.HemisphereLight(0xfffaea,0x707c5b,2.6));const sun=new THREE.DirectionalLight(0xffefd6,4);sun.position.set(-25,40,18);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-40,right:40,top:40,bottom:-40,far:120});sun.shadow.bias=-.0005;sun.shadow.normalBias=.03;scene.add(sun);const renderer=createRenderer(container);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;const camera=new THREE.PerspectiveCamera(42,1,.1,220);let az=.35,dist=57,elev=41;
const ground=block(scene,70,.3,65,0x9baa81,0,-.25,0);ground.material.map=lawnTexture();const parcel=block(scene,23,.12,44,0x93a575,0,0,0);parcel.material.map=lawnTexture();const road=block(scene,70,.07,5.5,0x8d9185,0,-.08,25);block(scene,70,.09,.2,0xcdcdb7,0,-.02,22.1);const border=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(23,.2,44)),new THREE.LineBasicMaterial({color:0xe9f2c4}));border.position.y=.17;scene.add(border);
const house=new THREE.Group();scene.add(house);block(house,15,.3,12,0xd4cebd,0,.15,7);block(house,15,3.05,12,0xeee9dc,0,1.8,7);hipRoof(house,0,7,16,13,2.2);block(house,6,.16,8,0xd5d1c4,4.2,.06,17);block(house,6,.18,3,0xcac1aa,-2,.08,-.5);block(house,2.2,.08,2,0xd3caba,-.7,.15,14);block(house,4.2,2.25,.12,0x737c70,4.5,1.45,13.08);for(let j=0;j<6;j++)block(house,4.2,.025,.13,0x596757,4.5,.5+j*.35,13.12);block(house,1.35,2.35,.15,0x8c7254,-.8,1.48,13.12);block(house,2.4,3,.14,0xc3bda8,-.8,1.8,13.04);block(house,1.3,2.35,.18,0x94775a,-.8,1.48,13.18);
for(const [x,z,side] of [[-5,13.08,0],[-2.9,13.08,0],[-7.58,5,1],[-7.58,9,1],[2,1,0]]){const w=1.55,h=1.8;const frame=block(house,w+.18,h+.18,.12,0x464d43,x,1.85,z);const glass=block(house,w,h,.14,0x849894,x,1.85,z+.025);glass.material.metalness=.35;glass.material.roughness=.18;if(side){frame.rotation.y=Math.PI/2;glass.rotation.y=Math.PI/2}}
for(let i=0;i<8;i++){const bush=new THREE.Mesh(new THREE.SphereGeometry(.45,12,10),material(0x667b4c));bush.position.set(-6.6+i*.85,.6,13.8);bush.castShadow=true;house.add(bush)}
const wild=new THREE.Group();scene.add(wild);for(let i=0;i<29;i++){const x=-9+(i*7.17%18),z=-18+(i*11.43%36);tree(wild,x,z,.5+(i%4)*.22)}
const context=new THREE.Group();scene.add(context);for(let i=0;i<22;i++){tree(context,i%2?-15-(i%3):15+(i%3),-23+i*2.05,1+(i%3)*.3)}for(let i=0;i<9;i++)tree(context,-24+i*6,-28,1.1+(i%3)*.2);for(const x of [-23,23]){block(context,10,3,9,0xd8d8c9,x,1.5,8);hipRoof(context,x,8,11,10,1.7);block(context,4,.07,12,0xc4c4b5,x,.02,18)}
const draw=()=>{camera.position.set(Math.sin(az)*dist,elev,Math.cos(az)*dist);camera.lookAt(0,1,2);renderer.render(scene,camera)};const resize=dimensions(container,renderer,camera,draw);function setState(key){house.visible=key==='house';wild.visible=key==='nature';parcel.material.color.setHex(key==='clean'?0xc4b594:0x93a575);parcel.material.map=key==='clean'?null:ground.material.map;parcel.material.needsUpdate=true;draw()}let drag;container.addEventListener('pointerdown',e=>{drag={x:e.clientX,az};container.setPointerCapture(e.pointerId)});container.addEventListener('pointermove',e=>{if(drag){az=drag.az-(e.clientX-drag.x)*.007;draw()}});for(const evt of ['pointerup','pointercancel'])container.addEventListener(evt,()=>drag=null);container.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowLeft')az-=.18;if(e.key==='ArrowRight')az+=.18;if(e.key==='ArrowUp')elev=Math.min(70,elev+4);if(e.key==='ArrowDown')elev=Math.max(16,elev-4);draw()});return{resize,setState,turn(n){az+=n;draw()},zoom(n){dist=clamp(dist+n,35,90);draw()},reset(){az=.35;dist=57;elev=41;draw()}}}
export function createPanorama(container){const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(75,1,.1,1100);const renderer=createRenderer(container);renderer.toneMapping=THREE.NoToneMapping;const geometry=new THREE.SphereGeometry(500,72,40);geometry.scale(-1,1,1);const mesh=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({color:0xffffff}));mesh.rotation.y=-Math.PI/2;scene.add(mesh);let yaw=0,pitch=0,drag,request=0;const cache=new Map();const draw=()=>{camera.lookAt(Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));renderer.render(scene,camera)};const resize=dimensions(container,renderer,camera,draw);const loader=new THREE.TextureLoader();async function show(url,angle){const ticket=++request;if(!cache.has(url))cache.set(url,loader.loadAsync(url).catch(e=>{cache.delete(url);throw e}));const texture=await cache.get(url);if(ticket!==request)return;texture.colorSpace=THREE.SRGBColorSpace;texture.repeat.set(2,2);texture.offset.set(-.5,-.5);mesh.material.map=texture;mesh.material.needsUpdate=true;yaw=angle;pitch=-.23;draw()}
const turn=n=>{yaw=clamp(yaw+n,-.85,.85);draw()};container.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,yaw,pitch};container.setPointerCapture(e.pointerId)});container.addEventListener('pointermove',e=>{if(!drag)return;yaw=clamp(drag.yaw-(e.clientX-drag.x)*.005,-.85,.85);pitch=clamp(drag.pitch+(e.clientY-drag.y)*.003,-.5,.15);draw()});for(const evt of ['pointerup','pointercancel'])container.addEventListener(evt,()=>drag=null);container.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowLeft')turn(-.15);if(e.key==='ArrowRight')turn(.15);if(e.key==='ArrowUp')pitch=clamp(pitch+.08,-.5,.15);if(e.key==='ArrowDown')pitch=clamp(pitch-.08,-.5,.15);draw()});return{resize,show,turn}}
